def can_make_increasing(n, m, a, b):
    # Flatten the matrices and sort them
    flat_a = sorted(a[i][j] for i in range(n) for j in range(m))
    flat_b = sorted(b[i][j] for i in range(n) for j in range(m))

    # Check if we can map each element in a to an element in b
    for i in range(n * m):
        if flat_a[i] != flat_b[i]:
            return "Impossible"

    # Try to rearrange elements in a to match b while maintaining strictly increasing property
    for i in range(n):
        for j in range(m):
            if a[i][j] != b[i][j]:
                found = False
                for k in range(i + 1, n):
                    if a[k][j] == b[i][j]:
                        # Swap rows
                        a[i], a[k] = a[k], a[i]
                        found = True
                        break
                if not found:
                    for l in range(j + 1, m):
                        if a[i][l] == b[i][j]:
                            # Swap columns
                            for x in range(n):
                                a[x][j], a[x][l] = a[x][l], a[x][j]
                            found = True
                            break
                if not found:
                    return "Impossible"

    return "Possible"

